import{_ as s,o as n,c as e,a5 as t}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"27. const 和 volatile 限定符","description":"The Little Book of C 中文版 — 27. const 和 volatile 限定符","frontmatter":{"title":"27. const 和 volatile 限定符","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","03-内存","中文"],"description":"The Little Book of C 中文版 — 27. const 和 volatile 限定符","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":27,"sidebarWeight":27,"alternateZh":"/posts/c教程/zh-CN/03-内存/027-const and volatile Qualifiers","alternateEn":"/posts/c教程/en-US/03-Working with Memory/027-const and volatile Qualifiers"},"headers":[],"relativePath":"posts/c教程/zh-CN/03-内存/027-const and volatile Qualifiers.md","filePath":"posts/c教程/zh-CN/03-内存/027-const and volatile Qualifiers.md","lastUpdated":1790163617000}'),o={name:"posts/c教程/zh-CN/03-内存/027-const and volatile Qualifiers.md"};function p(i,a,l,c,d,r){return n(),e("div",null,[...a[0]||(a[0]=[t(`<p>[English version](/posts/c教程/en-US/03-Working with Memory/027-const and volatile Qualifiers)</p><p>C 使您可以通过类型限定符对变量的使用方式进行细粒度控制。其中最重要的两个是<code>const</code>和<code>volatile</code>。它们看起来很简单，但在编写安全、可预测和高效的代码方面发挥着至关重要的作用，特别是在系统编程、嵌入式系统和多线程环境中。</p><h4 id="const-限定符" tabindex="-1">const 限定符 <a class="header-anchor" href="#const-限定符" aria-label="Permalink to &quot;const 限定符&quot;">​</a></h4><p><code>const</code>表示只读：变量一旦初始化，就无法修改。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>const int x = 10;</span></span>
<span class="line"><span>x = 20; // ❌ error: assignment of read-only variable</span></span></code></pre></div><p>这是对编译器和其他程序员的承诺，该值不会改变。</p><p><code>const</code>可以应用到很多事情上：</p><ul><li>变量</li><li>功能参数</li><li>指针</li><li>返回类型</li></ul><h4 id="const-与指针" tabindex="-1">const 与指针 <a class="header-anchor" href="#const-与指针" aria-label="Permalink to &quot;const 与指针&quot;">​</a></h4><p><code>const</code>使用指针可能很棘手，但遵循一致的规则。的位置<code>const</code>决定了什么是不能改变的。</p><table tabindex="0"><thead><tr><th>声明</th><th>意义</th></tr></thead><tbody><tr><td><code>const int *p;</code></td><td>指向常量数据的指针，数据不能改变</td></tr><tr><td><code>int *const p;</code></td><td>常量指针，指针不能改变，数据可以</td></tr><tr><td><code>const int *const p;</code></td><td>指针和数据都是常量</td></tr></tbody></table><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int value = 42;</span></span>
<span class="line"><span>const int *p1 = &amp;value;   // cannot modify *p1</span></span>
<span class="line"><span>int *const p2 = &amp;value;   // cannot reassign p2</span></span>
<span class="line"><span>const int *const p3 = &amp;value; // cannot change *p3 or p3</span></span></code></pre></div><h4 id="函数参数中的-const" tabindex="-1">函数参数中的 const <a class="header-anchor" href="#函数参数中的-const" aria-label="Permalink to &quot;函数参数中的 const&quot;">​</a></h4><p>将参数标记为<code>const</code>有助于防止意外修改并启用编译器优化。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void print_message(const char *msg) {</span></span>
<span class="line"><span>    printf(&quot;%s\\n&quot;, msg);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这里，<code>msg</code>是只读的；该函数无法修改它指向的字符串。</p><h4 id="小代码" tabindex="-1">小代码 <a class="header-anchor" href="#小代码" aria-label="Permalink to &quot;小代码&quot;">​</a></h4><p>这是一个程序演示<code>const</code>行动中：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>void show(const int *ptr) {</span></span>
<span class="line"><span>    // *ptr = 10;</span><span> // ❌ not allowed</span></span>
<span class="line"><span>    printf(&quot;Value: %d\\n&quot;, *ptr);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int num = 5;</span></span>
<span class="line"><span>    const int *p = #</span></span>
<span class="line"><span>    int *const q = #</span></span>
<span class="line"><span>    printf(&quot;num = %d\\n&quot;, num);</span></span>
<span class="line"><span>    // *p = 10;</span><span> // ❌ cannot modify value through const pointer</span></span>
<span class="line"><span>    *q = 15;</span><span>   // ✅ data modifiable through q</span></span>
<span class="line"><span>    printf(&quot;num after q change = %d\\n&quot;, num);</span></span>
<span class="line"><span>    show(&amp;num); // function accepts const pointer</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>编译并运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc const_demo.c -o const_demo</span></span>
<span class="line"><span>./const_demo</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>num = 5</span></span>
<span class="line"><span>num after q change = 15</span></span>
<span class="line"><span>Value: 15</span></span></code></pre></div><h4 id="不稳定的限定符" tabindex="-1">不稳定的限定符 <a class="header-anchor" href="#不稳定的限定符" aria-label="Permalink to &quot;不稳定的限定符&quot;">​</a></h4><p><code>volatile</code>告诉编译器变量可以随时更改，即使您的代码没有修改它。它阻止编译器优化读取或写入。</p><p>使用<code>volatile</code>什么时候：</p><ul><li>变量可以由硬件（例如，内存映射 I/O 寄存器）更改。</li><li>变量可以被另一个线程或信号处理程序修改。</li><li>您需要每次强制读取实际内存，而不是缓存值。</li></ul><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>volatile int sensor_value;</span></span>
<span class="line"><span>while (sensor_value &lt; 100) {</span></span>
<span class="line"><span>    // without volatile, compiler might optimize this loop away</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这里，<code>sensor_value</code>可能由硬件更新；<code>volatile</code>确保每次检查都会重新读取内存，而不是重用缓存的寄存器值。</p><h4 id="结合常量和易失性" tabindex="-1">结合常量和易失性 <a class="header-anchor" href="#结合常量和易失性" aria-label="Permalink to &quot;结合常量和易失性&quot;">​</a></h4><p>是的，您可以一起使用两者，一个值可能会意外更改，但您的代码无法修改它。</p><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>const volatile int status_register = 0x1234;</span></span></code></pre></div><p>这在嵌入式系统中很常见，其中硬件寄存器的位可能会因外部事件而改变。</p><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p>-<code>const</code>提高安全性和清晰度：使接口自我记录并帮助编译器发现错误。 -<code>volatile</code>保持并发或硬件驱动系统的正确性。</p><ul><li>它们共同帮助您平衡优化与精度，这在低级 C 编程中至关重要。</li></ul><p>如果您误用或忘记它们：</p><ul><li>您面临数据意外修改的风险（<code>const</code>).</li><li>编译器可能会删除关键读/写（<code>volatile</code>).</li></ul><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><p>编写一个程序尝试修改<code>const int</code>通过指针，观察编译器错误。</p><p>将变量声明为<code>volatile int counter</code>并在循环中递增它。</p><ul><li>然后删除<code>volatile</code>并检查生成的程序集<code>gcc -S</code>.</li></ul><p>创建一个函数<code>const char *msg</code>并尝试修改它，看看为什么它被禁止。</p><p>进行实验<code>const int *p</code>与<code>int *const p</code>了解他们的区别。</p><p>结合两者：<code>const volatile int flag;</code>并循环打印它。</p><p>在C中，<code>const</code>和<code>volatile</code>不仅仅是关键字，它们是合同。它们准确地告诉编译器如何使用内存，这有助于人类和机器安全地推理您的代码。</p>`,49)])])}const v=s(o,[["render",p]]);export{u as __pageData,v as default};
